// --- INPUT PRINCIPAL ---
const aiAgentRawOutput = $input.item.json.output; 
let standardizedOutput = {}; 
let parsedJson = null; 

// --- PASSO 1: Procurar JSON em qualquer string ---
if (typeof aiAgentRawOutput === 'string') {
  try {
    // Regex para encontrar o primeiro bloco JSON válido
    const match = aiAgentRawOutput.match(/{[\s\S]*}/);
    if (match) {
      let jsonString = match[0];

      // Remover comentários no estilo "// comentário"
      jsonString = jsonString.replace(/\/\/.*$/gm, '');

      parsedJson = JSON.parse(jsonString);
    }
  } catch (e) {
    console.error("Erro ao parsear JSON dentro da string:", e, aiAgentRawOutput);
    parsedJson = null;
  }
}
// --- PASSO 1B: Se já for objeto ---
else if (typeof aiAgentRawOutput === 'object' && aiAgentRawOutput !== null) {
  parsedJson = aiAgentRawOutput;
}

// --- PASSO 2: CLASSIFICAR O OUTPUT ---
if (parsedJson && typeof parsedJson === 'object' && parsedJson.action) {
  standardizedOutput = {
    type: 'action_json',
    action: parsedJson.action,
    sheet_data: parsedJson.sheet_data || null,
    bot_response: parsedJson.bot_response || parsedJson.final_bot_response_text || null
  };
} 
else if (typeof aiAgentRawOutput === 'string') {
  standardizedOutput = {
    type: 'text_response',
    message: aiAgentRawOutput
  };
} 
else {
  standardizedOutput = {
    type: 'text_response',
    message: "Desculpe, não entendi. Poderia repetir?"
  };
}

// --- PASSO 3: Propagação dos dados originais ---
standardizedOutput.client_id = $input.item.json.Numero || null;
standardizedOutput.instancia = $input.item.json.instacia || null;
standardizedOutput.user_message_original = $input.item.json.mensagem || null;
standardizedOutput.client_name_from_webhook = $input.item.json.nome || null;
standardizedOutput.current_date = $input.item.json.current_date || null;
standardizedOutput.current_time = $input.item.json.current_time || null;
standardizedOutput.initial_interaction_timestamp = $input.item.json.initial_interaction_timestamp || null;

return [{ json: standardizedOutput }];

// 1) Lê todos os itens de entrada (do Merge)
const inputs = $input.all();

// 2) Separa iniciais (item 0) e planilha (item 1, pode não existir)
const iniciais = inputs[0]?.json || {};
const planilha = inputs[1]?.json || {};

// 3) Junta ambos num único objeto
const merged = {
  ...iniciais,
  ...planilha
};

// 4) Remove chaves nulas/undefined
const cleanPayload = Object.fromEntries(
  Object.entries(merged)
    .filter(([_, v]) => v != null),
);

// 5) Gera timestamps em Europe/Lisbon
const now = new Date();
const options = {
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
  hour12: false, timeZone: 'Europe/Lisbon'
};
const initialInteractionTimestamp = new Intl.DateTimeFormat('pt-PT', options).format(now);
const currentDate  = new Intl.DateTimeFormat('pt-PT', {
  day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'Europe/Lisbon'
}).format(now);
const currentTime  = new Intl.DateTimeFormat('pt-PT', {
  hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Europe/Lisbon'
}).format(now);

// 6) Retorna um só item com tudo
return [{
  json: {
    ...cleanPayload,
    current_date: currentDate,
    current_time: currentTime,
    initial_interaction_timestamp: initialInteractionTimestamp
  }
}];
